import { getLanguage } from './i18n.js';
import { nativeDetails, musicWorlds, tracks, categories, projects, places, accessLevels, boundaries, authorityPrinciples } from './explorer-data.js';
const tr=x=>Array.isArray(x)?x[getLanguage()==='en'?1:0]:x;
const words={
 info:['Informationsansicht · eine Identität, viele Fähigkeiten','Information view · one identity, many capabilities'],
 native:['Dokumentierte Fähigkeiten und Konzepte. Diese Ansicht aktiviert keine Studio-, Analyse- oder Administrationssysteme.','Documented capabilities and concepts. This view activates no studio, analytics or administration systems.'],
 back:['Zurück zur Übersicht','Back to overview'],choose:['Wähle einen Bereich, um seine Bedeutung zu entdecken.','Choose an area to discover its meaning.'],
 tracks:['Tracks werden hier nach Freigabe vorgestellt.','Tracks will be presented here after approval.'],
 projects:['Hier erscheinen künftig freigegebene Projekte aus dem LYVRA Creative Universe.','Approved projects from the LYVRA Creative Universe will appear here.'],
 all:['Alle Kategorien','All categories'],status:['Veröffentlichungsstatus','Publication status'],
 world:['Symbolische Informationswelt · keine spielbare Game-Runtime','Symbolic information world · no playable game runtime'],
 gate:['Öffentliche Sicherheitsübersicht · keine Anmeldung oder Administration','Public security overview · no sign-in or administration'],
 boundaries:['Dokumentierte Systemgrenzen','Documented system boundaries'],authority:['LYVRA Authority Contract','LYVRA Authority Contract'],
 music:['Präsentation musikalischer Richtungen. Keine direkte Suno-Studio-2-Anbindung und keine behauptete Audio-Renderer- oder Mix-Validierung.','Presentation of musical directions. No direct Suno Studio 2 integration and no asserted audio-renderer or mix validation.'],
 details:['Projekt ansehen','View project'],platform:['Auf Plattform öffnen ↗','Open on platform ↗'],related:['Verbundener Websitebereich','Related website section'],source:['Öffentliche Entwicklungsübersicht','Public development overview']
};
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=tr(text);if(cls)n.className=cls;return n;};
// Freigegebene Links: keine javascript:, data:, Protokoll-relativen oder fremden lokalen Ziele.
export function safeLink(value){if(typeof value!=='string'||/[\s\\]/.test(value))return null;if(/^#[a-z][\w-]*$/.test(value))return value;if(/^\/(?!\/)[\w./-]*$/.test(value)&&!value.includes('..'))return value;try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null;}catch{return null;}}
const pair=x=>Array.isArray(x)&&x.length===2&&x.every(v=>typeof v==='string'&&v.length>0);
export function approvedTracks(data){return data.filter(x=>x&&x.approved===true&&typeof x.id==='string'&&/^[a-z][a-z0-9-]*$/.test(x.id)&&pair(x.title)&&typeof x.artist==='string'&&typeof x.genre==='string'&&pair(x.description)&&pair(x.publicationStatus));}
export function approvedProjects(data){return data.filter(x=>x&&x.approved===true&&typeof x.id==='string'&&/^[a-z][a-z0-9-]*$/.test(x.id)&&pair(x.title)&&categories.some(c=>c.id===x.category)&&pair(x.description)&&pair(x.publicationStatus));}
function link(label,href){const safe=safeLink(href);if(!safe||safe.startsWith('#')&&!document.getElementById(safe.slice(1)))return null;const a=el('a',label,'addon-link');a.href=safe;if(safe.startsWith('https:')){a.target='_blank';a.rel='noopener noreferrer';}return a;}
function mount(parent,id,title,subtitle,notice){const root=el('div',undefined,'lyvra-addon');root.id=id;root.setAttribute('role','region');root.setAttribute('aria-labelledby',id+'-title');const h=el('h3',title);h.id=id+'-title';root.append(h,el('p',subtitle,'addon-subtitle'),el('p',notice,'addon-notice'));parent.append(root);return root;}
function heading(root,title,subtitle,notice){root.replaceChildren();const h=el('h3',title);h.id=root.id+'-title';root.append(h,el('p',subtitle,'addon-subtitle'),el('p',notice,'addon-notice'));}
function cardSelector(root,items,selected,onSelect){const grid=el('div',undefined,'addon-grid');for(const item of items){const b=el('button',undefined,'addon-card');b.type='button';b.dataset.item=item.id;b.setAttribute('aria-pressed',String(selected===item.id));b.setAttribute('aria-controls',root.id+'-detail');b.append(el('strong',item.title));if(item.category)b.append(el('span',item.category));if(item.status)b.append(el('small',item.status));b.addEventListener('click',()=>onSelect(item.id));grid.append(b);}root.append(grid);return grid;}
function detail(root,item,back){const box=el('div',undefined,'addon-detail');box.id=root.id+'-detail';box.setAttribute('aria-live','polite');if(item){box.append(el('h4',item.title),el('p',item.description));if(item.status)box.append(el('p',item.status,'addon-status'));if(item.relatedSections){for(const id of item.relatedSections){if(document.getElementById(id)){const a=link(words.related,'#'+id);box.append(a);}}}if(back){const b=el('button',words.back,'addon-back');b.type='button';b.addEventListener('click',back);box.append(b);}}else box.append(el('p',words.choose));root.append(box);return box;}
export function extendFacetTabs(){const tabs=document.querySelector('.facet-tabs');for(const [id,item] of Object.entries(nativeDetails)){if(['sound','art'].includes(id))continue;const b=el('button',item.title);b.type='button';b.id='tab-'+id;b.dataset.facet=id;b.setAttribute('role','tab');b.setAttribute('aria-selected','false');b.setAttribute('aria-controls','facet-content');b.tabIndex=-1;tabs.append(b);}}
function renderNative(){const tab=document.querySelector('.facet-tabs [aria-selected="true"]');const item=nativeDetails[tab?.dataset.facet];document.querySelector('#native-facet-detail')?.remove();if(!item)return;const box=el('div',undefined,'native-facet-detail');box.id='native-facet-detail';box.append(el('h4',item.title),el('p',words.native,'addon-notice'));const ul=el('ul');for(const text of item.topics)ul.append(el('li',text));box.append(ul);document.querySelector('#facet-content').append(box);}
function renderTracks(root,genre){const list=approvedTracks(tracks).filter(t=>t.genre===genre);root.append(el('h4','Track Explorer'));if(!list.length){root.append(el('p',words.tracks,'addon-empty'));return;}const grid=el('div',undefined,'addon-grid');for(const t of list){const card=el('article',undefined,'addon-content-card');card.append(el('h4',t.title),el('p',t.artist+' · '+t.genre),el('p',t.description),el('p',t.publicationStatus,'addon-status'));const image=safeLink(t.artwork);if(image){const img=el('img');img.src=image;img.alt=tr(t.title);img.loading='lazy';card.prepend(img);}if(Number.isFinite(t.durationSeconds)&&t.durationSeconds>0)card.append(el('p',Math.floor(t.durationSeconds/60)+':'+String(Math.floor(t.durationSeconds%60)).padStart(2,'0')));if(t.audioVerified===true&&safeLink(t.audioUrl)){const audio=el('audio');audio.controls=true;audio.preload='none';audio.src=safeLink(t.audioUrl);audio.setAttribute('aria-label',tr(t.title));card.append(audio);}const a=link(words.platform,t.platformUrl);if(a)card.append(a);grid.append(card);}root.append(grid);}
function gallery(root,state){heading(root,'LYVRA Creative Universe','Where imagination meets architecture.',words.info);const filter=el('div',undefined,'addon-filters');const opts=[{id:'all',title:words.all},...categories];for(const c of opts){const b=el('button',c.title,'addon-filter');b.type='button';b.dataset.item=c.id;b.setAttribute('aria-pressed',String(state.category===c.id));b.addEventListener('click',()=>{state.category=c.id;state.project=null;gallery(root,state);root.querySelector(`[data-item="${c.id}"]`).focus();});filter.append(b);}root.append(filter);const category=categories.find(c=>c.id===state.category);if(category)root.append(el('p',category.description,'addon-notice'));const list=approvedProjects(projects).filter(p=>state.category==='all'||p.category===state.category);const selected=list.find(p=>p.id===state.project);if(selected){const box=detail(root,{...selected,status:selected.publicationStatus},()=>{state.project=null;gallery(root,state);root.querySelector(`[data-project="${selected.id}"]`)?.focus();});for(const field of ['internalLink','externalLink']){const a=link(words.details,selected[field]);if(a)box.append(a);}return;}if(!list.length){root.append(el('p',words.projects,'addon-empty'));return;}const grid=el('div',undefined,'addon-grid');for(const p of list){const card=el('article',undefined,'addon-content-card');card.append(el('h4',p.title),el('p',p.description),el('p',p.publicationStatus,'addon-status'));if(/^\d{4}-\d{2}-\d{2}$/.test(p.publicationDate||'')){const time=el('time',p.publicationDate);time.dateTime=p.publicationDate;card.append(time);}if(safeLink(p.image)&&pair(p.imageAlt)){const img=el('img');img.src=safeLink(p.image);img.alt=tr(p.imageAlt);img.loading='lazy';card.prepend(img);}const b=el('button',words.details,'addon-back');b.type='button';b.dataset.project=p.id;b.addEventListener('click',()=>{state.project=p.id;gallery(root,state);root.querySelector('.addon-back').focus();});card.append(b);grid.append(card);}root.append(grid);}
export function installExplorers(){
 const sound=mount(document.querySelector('#sound'),'music-universe','LYVRA Music Universe','Explore the frequencies of 666SOUNDsDESIGn.',words.music);
 const lab=mount(document.querySelector('#lab .wrap'),'creative-universe','LYVRA Creative Universe','Where imagination meets architecture.',words.info);
 const world=mount(document.querySelector('#world'),'universe-world-explorer','LYVRA Universe Explorer','Explore the worlds of resonance, creation and evolution.',words.world);
 const gateway=mount(document.querySelector('#evolution'),'secure-system-gateway','LYVRA Secure System Gateway','One identity. Controlled access. Verified boundaries.',words.gate);
 let selectedMusic='psytrance',selectedWorld=null,selectedAccess='public';const galleryState={category:'all',project:null};
 const restore=(root,id)=>root.querySelector(`[data-item="${id}"]`)?.focus();
 function music(){heading(sound,'LYVRA Music Universe','Explore the frequencies of 666SOUNDsDESIGn.',words.music);cardSelector(sound,musicWorlds,selectedMusic,id=>{selectedMusic=id;music();restore(sound,id);});const item=musicWorlds.find(x=>x.id===selectedMusic);sound.dataset.selection=selectedMusic;detail(sound,item);renderTracks(sound,item.title);}
 function worlds(){heading(world,'LYVRA Universe Explorer','Explore the worlds of resonance, creation and evolution.',words.world);cardSelector(world,places,selectedWorld,id=>{selectedWorld=id;worlds();restore(world,id);});world.dataset.selection=selectedWorld||'';detail(world,places.find(x=>x.id===selectedWorld),()=>{const prev=selectedWorld;selectedWorld=null;worlds();restore(world,prev);});}
 function access(){heading(gateway,'LYVRA Secure System Gateway','One identity. Controlled access. Verified boundaries.',words.gate);cardSelector(gateway,accessLevels,selectedAccess,id=>{selectedAccess=id;access();restore(gateway,id);});detail(gateway,accessLevels.find(x=>x.id===selectedAccess));gateway.append(el('h4',words.boundaries));const dl=el('dl',undefined,'addon-boundaries');for(const [name,description] of boundaries){dl.append(el('dt',name),el('dd',description));}gateway.append(dl,el('h4',words.authority));const ul=el('ul');for(const p of authorityPrinciples)ul.append(el('li',p));gateway.append(ul,link(words.source,'#lyvra-system-evolution'));}
 function render(){const focused=document.activeElement;const rid=focused?.closest('.lyvra-addon')?.id;const key=focused?.dataset.item;music();gallery(lab,galleryState);worlds();access();renderNative();if(rid&&key)restore(document.getElementById(rid),key);}
 document.addEventListener('lyvra:facetselected',renderNative);document.addEventListener('lyvra:languagechange',render);render();
}
